function spin(){ return [SLOT_SYMBOLS[Math.floor(Math.random()*SLOT_SYMBOLS.length)], SLOT_SYMBOLS[Math.floor(Math.random()*SLOT_SYMBOLS.length)], SLOT_SYMBOLS[Math.floor(Math.random()*SLOT_SYMBOLS.length)]]; }
function payout(syms){
  var a=syms[0],b=syms[1],c=syms[2];
  if(a===b&&b===c) return PAYOUT[a]*3;
  if(a===b||b===c||a===c) return 2;
  return 0;
}
var EXPORTS={spin:spin,payout:payout,SLOT_SYMBOLS:SLOT_SYMBOLS,PAYOUT:PAYOUT};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
